import {createSession,reduce,truth,predict,isWitness,fresh,summary,restore,RULES,key,archiveSession,history,comparison} from './engine.js';
const root=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const STORE='fixiverse-foundry-v1';let state=createSession(),storageOK=!window.fixiverseStorage.memoryOnly,notice='',feeling='ready';
try{const saved=window.fixiverseStorage.getItem(STORE);if(saved)state=restore(saved);}catch{notice='A saved session could not be restored. Your new investigation is ready.';}
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" data-focus="${action}-${extra.match(/data-value="([^"]*)"/)?.[1]||'button'}" ${extra}>${label}</button>`;
const fraction=n=>`<span class="fraction" aria-label="one over ${n}"><em>1</em><i>${n}</i></span>`;
const sideName=s=>({left:'the left piece',right:'the right piece',equal:'both pieces equally',unsure:'not sure yet'}[s]);
const showPair=p=>`<span class="mini-fractions">${fraction(p[0])}<b>${truth(p)==='equal'?'=':truth(p)==='left'?'&gt;':'&lt;'}</b>${fraction(p[1])}</span>`;
function robot(fixed=false){return`<div class="machine-art" aria-hidden="true"><div class="robot ${fixed?'fixed':''}"><div class="robot-screen"><i class="eye"></i><i class="eye"></i></div><div class="robot-mouth"></div></div></div>`;}
function machine(){const fixed=state.rule==='smaller';return`<aside><section class="machine-panel"><div class="machine-label"><span></span> ${fixed?'REPAIR INSTALLED':'RULE UNDER INVESTIGATION'}</div>${robot(fixed)}<h3>Meet Pip, the sorter.</h3><p>${fixed?'Your evidence helped Pip change its rule.':'Pip follows a rule. You get to check it.'}</p><div class="rule-readout">${RULES[state.rule].name}</div><p>${fixed?'For one piece each, Pip now chooses the smaller bottom number.':'Pip chooses the larger bottom number. Does the size of the piece agree?'}</p><p class="machine-scope">Always compare <strong>ONE piece</strong> from <strong>same-sized wholes</strong>.</p></section>${state.witness?`<section class="evidence"><div class="eyebrow">Your saved evidence</div>${showPair(state.witness.pair)}<p>You found a pair where Pip's old rule disagreed with the piece sizes.</p></section>`:''}<section class="help-card"><h3>A little help is welcome.</h3><p>Try a visual hint, or work through it with your tutor.</p>${button('Show me a way to compare','help','')}</section></aside>`;}
function bars(pair,editable=false){return pair.map((d,i)=>`<div class="bar-row ${i?'right':'left'}">${fraction(d)}<div><div class="bar-meta"><span>${i?'RIGHT':'LEFT'} WHOLE</span><span>1 piece selected</span></div><div class="fraction-bar" role="img" aria-label="${i?'Right':'Left'} whole split into ${d} equal parts, one part selected">${Array.from({length:d},(_,j)=>`<div class="part ${j===0?'selected':''}"></div>`).join('')}</div>${editable?`<div class="denominator" role="group" aria-label="Number of parts in ${i?'right':'left'} whole"><span>Equal parts</span>${Array.from({length:7},(_,j)=>`<button data-action="denominator" data-side="${i}" data-number="${j+2}" data-focus="denom-${i}-${j+2}" class="${d===j+2?'selected':''}" aria-pressed="${d===j+2}">${j+2}</button>`).join('')}</div>`:''}</div></div>`).join('');}
function choices(action,selected,disabled=false){return`<div class="choices" role="group" aria-label="Which piece is larger?">${[['left','← Left piece'],['equal','Same size'],['right','Right piece →']].map(([v,l])=>button(l,action,`choice ${selected===v?'selected':''}`,`data-value="${v}" aria-pressed="${selected===v}" ${disabled?'disabled':''}`)).join('')}</div>${button('I’m not sure yet',action,`unsure ${selected==='unsure'?'selected':''}`,`data-value="unsure" aria-pressed="${selected==='unsure'}" ${disabled?'disabled':''}`)}`;}
function overlay(pair){return state.overlay?`<div class="overlay ${state.overlay==='overlay'?'stacked':'distinct'}"><div class="eyebrow">${state.overlay==='overlay'?'See the pieces overlap':'Line up the selected pieces'}</div><div role="img" aria-label="Selected pieces aligned at the same starting point"><div class="overlay-bar" style="width:${100/pair[0]}%"></div><div class="overlay-bar purple" style="width:${100/pair[1]}%"></div></div><p class="hint-text">Both whole bars have the same length. Which selected piece reaches farther?</p></div>`:'';}
function heading(kicker,title,description){return`<div class="intro-row"><div><div class="eyebrow">${kicker}</div><h1 tabindex="-1" id="screen-title">${title}</h1><p class="lede">${description}</p></div><div class="intro-tools">${button('◖ Read aloud','read','quiet audio','aria-label="Read the screen aloud"')}${button('Need a hint?','help','quiet')}</div></div>`;}
const scope='<div class="scope">Same-sized wholes. Equal parts. Keep <strong>one piece</strong> from each.</div>';
function welcome(){return`<section class="welcome"><div class="welcome-grid"><div><div class="eyebrow">A small experiment. A big discovery.</div><h1 tabindex="-1" id="screen-title">A small experiment.<br>A discovery of your own.</h1><p class="lede">Something's off at the Fraction Foundry. Build an experiment, check Pip's rule, and make a repair of your own.</p><p class="hint-text" style="margin-top:25px">How are you feeling about trying?</p><div class="feeling" role="group" aria-label="How do you feel before starting?">${[['ready','Ready to explore'],['unsure','A little unsure'],['help','I’d like some help'],['skip','Skip']].map(([v,l])=>button(l,'feeling',feeling===v?'selected':'',`data-value="${v}" aria-pressed="${feeling===v}"`)).join('')}</div>${button('Start investigating <span aria-hidden="true">↗</span>','start')}<p class="hint-text">One short mission · Your pace · Help whenever you need it</p></div><div class="welcome-art" aria-label="Pip the sorter with a half and a quarter"><div class="sticky-note">FOUND: one curious mind<br>NEEDED: one good experiment</div><div class="robot" aria-hidden="true"><div class="robot-screen"><i class="eye"></i><i class="eye"></i></div><div class="robot-mouth"></div></div><div class="float-card a"><span class="eyebrow">One half</span><div class="mini-bar"><i></i><i></i></div></div><div class="float-card b"><span class="eyebrow">One quarter</span><div class="mini-bar"><i></i><i></i><i></i><i></i></div></div></div></div><div class="welcome-bottom"><div><b>01 &nbsp; Make a discovery</b><p>Use equal pieces to test an idea.</p></div><div><b>02 &nbsp; Make a repair</b><p>Change the rule with your evidence.</p></div><div><b>03 &nbsp; Make it your own</b><p>Keep a record of what you figured out.</p></div></div></section>`;}
function prediction(){const answered=state.prediction!==null;return`${heading('01 / Notice','Which piece is bigger?','These whole bars are the same size. Which selected piece do you think is larger?')}<div class="workspace-grid"><section class="panel"><div class="panel-head"><span class="panel-title">✦ &nbsp; Your first prediction</span><span class="label">Take your time</span></div><div class="panel-body">${scope}${bars([2,4])}${choices('prediction',state.prediction,answered)}${answered?`<div class="result"><strong>You made a prediction. Let's investigate.</strong>Pip chose the right piece because 4 is larger than 2. Look at the selected pieces. Does Pip's choice make sense?</div><div class="btn-row">${button('Build my experiment →','explore')}</div>`:'<p class="hint-text">It’s okay to be unsure. A prediction is a place to start.</p>'}${overlay([2,4])}</div></section>${machine()}</div>`;}
function investigation(){const t=state.tested,valid=t&&t.choice===t.truth&&isWitness(t.pair);let feedback='';if(t){if(t.truth===t.machine)feedback='<strong>These pieces agree with Pip.</strong>Pip and the piece sizes agree here. Try a different number of parts.';else if(t.choice!==t.truth)feedback='<strong>Let’s look at the pieces together.</strong>Try lining them up with a visual hint. You can change your prediction and run the experiment again.';else feedback='<strong>You found something worth keeping.</strong>Your comparison and Pip’s choice disagree. The pieces show why the rule needs a repair.';}
return`${heading('02 / Experiment','Make your own pair.','Find an example that shows whether Pip’s rule works.')}<div class="workspace-grid"><section class="panel"><div class="panel-head"><span class="panel-title">⌘ &nbsp; Your experiment bench</span><span class="label">${state.experiments.length} ${state.experiments.length===1?'test':'tests'} run</span></div><div class="panel-body">${scope}${bars(state.pair,true)}<p class="reason-label">Which shaded piece is bigger?</p>${choices('choose',state.choice)}<div class="btn-row">${button('Run experiment <span aria-hidden="true">↗</span>','test','btn',state.choice===null||state.tested?'disabled':'')}<span class="hint-text">Change the parts. Test your idea.</span></div>${t?`<div class="result ${valid?'':'soft'}">${feedback}<p style="margin-bottom:0">Pip picked <b>${sideName(t.machine)}</b>. The actual larger piece is <b>${sideName(t.truth)}</b>.</p></div>${valid?`<div class="btn-row">${button('Save evidence and repair →','save')}</div>`:''}`:''}${overlay(state.pair)}</div></section>${machine()}</div>`;}
function repair(){const selected=state.candidate;return`${heading('03 / Repair','Help Pip choose a better rule.','Use the example you built to help Pip compare fractions.')}<div class="workspace-grid"><section class="panel"><div class="panel-head"><span class="panel-title">⚙ &nbsp; Pip’s rule workshop</span><span class="label">Your turn to repair</span></div><div class="panel-body">${scope}<div class="rule-options" role="group" aria-label="Choose a replacement rule">${Object.entries(RULES).map(([id,r])=>`<button class="rule-option ${selected===id?'selected':''}" data-action="rule" data-focus="rule-${id}" data-value="${id}" aria-pressed="${selected===id}"><span class="radio" aria-hidden="true"></span><span><b>${r.name}</b><small>${r.short}</small></span></button>`).join('')}</div><section class="repair-evidence"><h3>Your evidence, ready to explain</h3>${bars(state.witness.pair)}${overlay(state.witness.pair)}<p>Point to the piece that reaches farther. Use these pieces to choose your repair.</p></section><p class="reason-label">What does your example show?</p><div class="reason-options" role="group" aria-label="Choose your explanation">${[['parts','More equal parts makes each one piece smaller.'],['same','The selected pieces are always the same size.'],['tutor','I’d like to explain it with my tutor.']].map(([id,text])=>button(text,'reason',state.reason===id?'selected':'',`data-value="${id}" aria-pressed="${state.reason===id}"`)).join('')}</div><div class="btn-row">${button('Test this repair','patch','btn',!selected||!state.reason?'disabled':'')}</div>${state.message?`<div class="result soft">${esc(state.message)}</div>`:''}${state.repairPassed?`<div class="replay"><div><small>Before your repair</small>Pip chose <b>${sideName(predict('bigger',state.witness.pair))}</b>.</div><div><small>After your repair</small>Pip chooses <b>${sideName(predict('smaller',state.witness.pair))}</b>.</div></div><div class="result"><strong>Your repair agrees with your evidence.</strong>For ONE piece from matching wholes, fewer equal parts means a larger piece. Let's try examples you haven't seen.</div><div class="btn-row">${button('Try fresh examples →','begin-check')}</div>`:''}</div></section>${machine()}</div>`;}
function verification(){const c=state.checks[state.checkIndex],r=state.checkResult;return`${heading('04 / Check','Try three new pairs.','Make your own comparison. Pip will keep its answer hidden until you’re ready.')}<div class="workspace-grid"><section class="panel"><div class="panel-head"><span class="panel-title">✦ &nbsp; Fresh example ${state.checkIndex+1} of 3</span><span class="check-dots" aria-hidden="true">${[0,1,2].map(i=>`<i class="${i===state.checkIndex?'active':''}"></i>`).join('')}</span></div><div class="panel-body">${scope}${bars(c.pair)}${choices('check-choice',state.checkChoice,!!r)}${!r?`<div class="btn-row">${button('Check my comparison','check','btn',state.checkChoice===null?'disabled':'')}</div>`:`<div class="result ${r.correct?'':'soft'}"><strong>${r.correct?'Your comparison fits the pieces.':'Here is what the pieces show.'}</strong>${r.truth==='equal'?'Both selected pieces have the same size.':`${r.truth==='left'?'The left':'The right'} selected piece is larger.`} ${r.correct?'You tried a fresh example.':'You can keep practicing with support.'}</div><div class="btn-row">${button(state.checkIndex<2?'Next example →':'Keep my repair card →','next-check')}</div>`}${overlay(c.pair)}</div></section>${machine()}</div>`;}
function completion(){const m=summary(state),checked=m.freshAnswered>0;return`${heading('Your investigation','Look what your curiosity made possible.','Keep an honest record of your experiment, your repair, and what you want to try next.')}<div class="summary-grid"><section class="certificate"><div class="seal" aria-hidden="true">✦</div><div class="eyebrow">Fixiverse / Repair record</div><h2>${m.ruleRepaired?'The Fraction Foundry':'An investigation worth keeping'}</h2><p>${m.witness?`You built an example with <strong>1/${m.witness[0]}</strong> and <strong>1/${m.witness[1]}</strong>. It showed where Pip's original rule failed.`:'You started exploring how one piece changes when a whole has more equal parts.'}</p><p>${m.ruleRepaired?'You installed a rule for comparing ONE piece from matching wholes.':'You can return to investigate the rule again.'}</p><div class="stats"><div><b>${m.experiments}</b><small>experiments tried</small></div><div><b>${checked?`${m.freshCorrect}/${m.freshAnswered}`:': '}</b><small>fresh comparisons correct</small></div></div><p class="hint-text">Instructional hints used: ${m.instructionalHints}. Tutor help: ${esc(m.adultHelp)}. Normal access tools stay available.</p><p class="hint-text">This is a record of one session, not a claim of mastery.</p></section><section class="panel"><div class="panel-body"><h2>What would you like next?</h2><p class="lede">You get to decide. Asking for help is a useful next step, too.</p><div class="reason-options">${[['ready','I’m ready to try another example'],['unsure','I want a little more practice'],['help','I’d like to work with my tutor'],['skip','I’m happy to finish here']].map(([v,l])=>button(l,'confidence',state.confidenceAfter===v?'selected':'',`data-value="${v}" aria-pressed="${state.confidenceAfter===v}"`)).join('')}</div><div class="btn-row">${button('Save repair record ↓','export')}<button class="btn secondary" data-growth="practice" data-mission="fraction">A little practice for me ↗</button></div>${m.ruleRepaired&&state.verificationAttempts<2?`<div class="btn-row">${button('Try 3 more fresh examples','begin-check','btn secondary')}</div>`:''}<div class="btn-row">${button('Start a new investigation','restart','quiet')}</div><p class="hint-text">Your current session is saved on this device when browser storage is available.</p></div></section></div>`;}
function completed(p){return p==='predict'?state.prediction!==null:p==='build'?!!state.witness:p==='repair'?state.repairPassed:p==='verify'?state.checks.length===3&&state.checks.every(c=>c.choice!==null):false;}function render(focus=false){const active=document.activeElement?.dataset?.focus;const phases=['predict','build','repair','verify','complete'],pos=phases.indexOf(state.phase);root.className=['storybook-mission','fraction-chapter',state.access.large?'large':'',state.access.motion?'reduced':''].join(' ');root.innerHTML=`<header><div class="brand"><span class="brand-icon" aria-hidden="true"><i></i><i></i><i></i><i></i></span>fixiverse<small>THE CURIOSITY WORKSHOP</small></div><div class="header-actions"><button class="quiet" data-hub="tutor">Tutor workspace</button><button class="quiet" data-hub="home">⌂ My workshop</button>${button('My discoveries','history','quiet')}${button('◷ Pause','pause','quiet','aria-label="Pause and save"')}${button('⚙ Settings','settings','quiet','aria-label="Open accessibility settings"')}${button('For tutors ↗','tutors','quiet','aria-label="For tutors: session information"')}</div></header><div class="shell"><div class="topline"><span class="mission-chip"><i class="dot"></i> MISSION 01 &nbsp; / &nbsp; THE FRACTION FOUNDRY</span><span class="save-note">${storageOK?'Progress stays on this device':'Storage unavailable · export to keep your work'}</span></div><div class="layout">${state.phase!=='welcome'?`<nav class="steps" aria-label="Mission progress">${[['predict','Notice'],['build','Experiment'],['repair','Repair'],['verify','Check'],['complete','Keep it']].map(([p,t],i)=>`<div class="step ${state.phase===p?'active':completed(p)?'done':''}" ${state.phase===p?'aria-current="step"':''}><b>${completed(p)?'✓':String(i+1).padStart(2,'0')}</b>${t}</div>`).join('')}<div class="steps-note">Good discoveries<br>start with a question.<br><br>No rush. No lost points.</div></nav>`:'<div class="steps"><div class="eyebrow" style="padding:12px 8px">Made for<br>curious minds</div><div class="steps-note">An adventure in<br>fractions, evidence,<br>and trying again.</div></div>'}<main id="main">${notice?`<div class="error-banner" role="status">${esc(notice)}</div>`:''}${({welcome,predict:prediction,build:investigation,repair,verify:verification,complete:completion}[state.phase])()}</main></div></div><footer><span>✦ &nbsp; A little curiosity goes a long way.</span><span>Playable prototype · Built for learning at your pace <span class="footer-heart">♡</span></span></footer>`;window.fixiverseMissionUI(root,{phase:'fraction-'+state.phase,instruction:({welcome:'Choose how you feel, or choose Skip. Then select Start investigating.',predict:state.prediction===null?'Look at the shaded pieces. Choose Left piece, Same size, Right piece, or I am not sure yet.':'Your prediction is saved. Select Build my experiment to test an example.',build:state.tested?(state.tested.choice!==state.tested.truth?'Look at the shaded pieces or ask for a hint. Choose again, then run the experiment.':isWitness(state.tested.pair)?'Your example shows a mistake in Pip’s rule. Select Save evidence and repair.':'Pip agrees with these pieces. Change one of the numbers and try again.'):state.choice===null?'Use the number buttons to change the equal parts. Then choose which shaded piece is bigger.':'Your choice is selected. Select Run experiment to compare it with Pip.',repair:state.repairPassed?'Your rule fits this example. Select Try fresh examples to check it on new pairs.':!state.candidate?'Choose the rule that fits your saved pieces.':!state.reason?'Now choose what your example shows.':'Select Test this repair. Your evidence will check the rule.',verify:state.checkResult?'Read the result. Then select the next example.':'Choose which piece is bigger. Then select Check my comparison.',complete:'Choose what you would like to try next. You can save your repair record or return to the bookshelf.'})[state.phase]});if(focus)document.querySelector('#screen-title')?.focus({preventScroll:true});else if(active)document.querySelector(`[data-focus="${active}"]`)?.focus({preventScroll:true});}
function dispatch(a){const phase=state.phase;try{state=reduce(state,a);notice='';save();render(phase!==state.phase);if(["TEST","CHECK"].includes(a.type)){const result=root.querySelector(".result");if(result){result.tabIndex=-1;result.focus({preventScroll:true});}}if(state.message)announce(state.message);}catch(e){notice=e.message;render();announce(e.message);}}
function save(){if(window.fixiverseTour?.active())return;try{if(state.phase==='complete')archiveSession(state,summary(state),window.fixiverseStorage);window.fixiverseStorage.setItem(STORE,JSON.stringify(state));window.fixiverseStorage.setItem("fixiverse-access-v1",JSON.stringify(state.access));storageOK=!window.fixiverseStorage.memoryOnly;}catch{storageOK=false;}}
function announce(t){document.querySelector('#announcement').textContent=t;}
function modal(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('×','close','quiet icon-button','aria-label="Close dialog"')}</div>${body}`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();}
function help(){if(state.phase==='welcome'||state.phase==='complete'){modal('Support is part of the adventure','<p>Use the settings to enlarge text or reduce motion. During the mission, you can line up pieces, see a worked example, or ask your tutor.</p>'+button('Got it','close'));return;}modal('Let’s look a little closer.',`<p>Choose a way to compare. These hints are recorded as instructional help, so your repair card tells the full story.</p><div class="reason-options">${button('Line up the selected pieces','hint','','data-value="align"')}${button('Overlay the two selected pieces','hint','','data-value="overlay"')}${button('Show a worked half-and-quarter example','hint','','data-value="worked"')}${button('I’m working with my tutor','adult-help')}</div>`);}
function exportRecord(){const data={...summary(state),events:state.events};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fixiverse-repair-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Repair record downloaded.');}
function read(){if(!('speechSynthesis'in window)){modal('Read-aloud is unavailable','<p>This browser does not provide read-aloud. Your tutor can read the short instructions with you. All controls remain available.</p>'+button('Continue','close'));return;}const text=document.querySelector('main')?.innerText;if(!text)return;const u=new SpeechSynthesisUtterance(text);u.rate=.85;u.onerror=()=>announce('Read-aloud could not play. Please try your device’s reading tools or ask your tutor.');speechSynthesis.cancel();speechSynthesis.speak(u);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const v=b.dataset.value;switch(b.dataset.action){
case'history':{const records=comparison(history(window.fixiverseStorage));modal('My discoveries',`<p>Each visit is one investigation. Different examples and different help can affect results.</p>${records.length?records.map((r,i)=>`<section class="evidence"><h3>Visit ${records.length-i}</h3><p>${esc(new Date(r.date).toLocaleDateString())} · ${r.answered?`${r.correct}/${r.answered} fresh comparisons correct`:'No fresh comparisons attempted yet'}</p><p>Hints: ${r.hints} · Tutor help: ${esc(r.help)}</p><p>My next step: ${esc(r.reflection||'not chosen yet')}</p></section>`).join(''):'<p>Your first completed investigation will appear here. Keep exploring at your pace.</p>'}${button('Back to the workshop','close')}`);break;}
case'close':dialog.close();break;
case'feeling':feeling=v;render();break;
case'start':dispatch({type:'START',feeling});break;
case'prediction':dispatch({type:'PREDICT',choice:v});break;
case'explore':dispatch({type:'EXPLORE'});break;
case'denominator':{const p=[...state.pair];p[+b.dataset.side]=+b.dataset.number;dispatch({type:'PAIR',pair:p});break;}
case'choose':dispatch({type:'CHOOSE',choice:v});break;
case'test':dispatch({type:'TEST'});announce('Experiment run. Read the result below the controls.');break;
case'save':dispatch({type:'SAVE'});break;
case'rule':dispatch({type:'RULE',rule:v});break;
case'reason':dispatch({type:'REASON',reason:v});break;
case'patch':dispatch({type:'PATCH'});if(state.repairPassed)announce('Your repair agrees with your saved evidence. Fresh examples are ready.');break;
case'begin-check':dispatch({type:'BEGIN_CHECK'});break;
case'check-choice':dispatch({type:'CHECK_CHOICE',choice:v});break;
case'check':dispatch({type:'CHECK'});announce(state.checkResult?.correct?'Your comparison fits the pieces.':'Look at the comparison result. You can keep practicing.');break;
case'next-check':dispatch({type:'NEXT_CHECK'});break;
case'confidence':dispatch({type:'CONFIDENCE',value:v});announce('Your next-step choice is saved.');break;
case'help':help();break;
case'hint':dialog.close();dispatch({type:'HINT',id:v});if(v==='worked')modal('One example, together.',`${scope}${bars([2,4])}<p>One piece from two equal parts is larger than one piece from four equal parts. The wholes are the same size. Try looking for that relationship in your own pair.</p>${button('Back to my experiment','close')}`);else announce('Selected pieces are now aligned below the controls.');break;
case'adult-help':dialog.close();dispatch({type:'ADULT_HELP'});announce('Tutor support recorded.');break;
case'pause':modal('Your curiosity can wait.',`<p>${storageOK?'Your progress is saved on this device. Come back whenever you’re ready.':'Browser storage is unavailable. Download a record of your work before leaving.'}</p><div class="btn-row">${button('Keep exploring','close')}${button('Finish for today','finish','btn secondary')}</div>`);break;
case'finish':dialog.close();dispatch({type:'FINISH'});break;
case'settings':modal('Make yourself comfortable.',`<p>These access tools stay available throughout the mission.</p><div class="reason-options">${button('Larger text: '+(state.access.large?'on':'off'),'access','','data-value="large" aria-pressed="'+state.access.large+'"')}${button('Reduced motion: '+(state.access.motion?'on':'off'),'access','','data-value="motion" aria-pressed="'+state.access.motion+'"')}</div><p class="hint-text">Read-aloud uses your browser’s speech service when available. Keyboard controls work throughout. No microphone or camera is required.</p>${button('Back to the workshop','close')}`);break;
case'access':dispatch({type:'ACCESS',setting:v});b.setAttribute('aria-pressed',String(state.access[v]));b.textContent=(v==='large'?'Larger text: ':'Reduced motion: ')+(state.access[v]?'on':'off');break;
case'tutors':modal('A small investigation, with real evidence.',`<p>For learners familiar with equal parts. This mission compares <b>1/b and 1/d of identical wholes</b>, with denominators 2 to 8.</p><p>Learning from errors has research precedents. This prototype explores child-built evidence and rule repair; it has not been validated with learners.</p><p>Access tools are separate from instructional hints. Unreported adult help may be unknown. No name or diagnosis is required.</p><pre>${esc(JSON.stringify(summary(state),null,2))}</pre><div class="btn-row">${button('Download session record','export')}${button('New investigation','restart','btn secondary')}</div>`);break;
case'restart':if(dialog.open)dialog.close();modal('Start a fresh investigation?',`<p>Starting over replaces the session saved on this device. You can download its record first.</p><div class="btn-row">${button('Download current record','export','btn secondary')}${button('Start fresh','confirm-restart')}${button('Keep current session','close','quiet')}</div>`);break;
case'confirm-restart':dialog.close();const accessBeforeRestart={...state.access};state=createSession();state.access=accessBeforeRestart;state.seen.push(...history(window.fixiverseStorage).flatMap(r=>r.seen||[]));notice='';save();render(true);break;
case'export':exportRecord();break;
case'read':read();break;
}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
render();










let fractionTourSnapshot=null;
window.fixiverseFraction={tourScene:stage=>{document.title='Fixiverse · Fraction Foundry · Guided tour';if(fractionTourSnapshot===null)fractionTourSnapshot=structuredClone({state,feeling,notice,storageOK});const access={...state.access};state=window.fixiverseJourneyModels.fractionJourney(stage);state.access=access;render(true);},endTour:()=>{if(fractionTourSnapshot!==null){({state,feeling,notice,storageOK}=fractionTourSnapshot);fractionTourSnapshot=null;}},show:()=>{try{const prefs=JSON.parse(window.fixiverseStorage.getItem("fixiverse-access-v1")||"null");if(prefs)state.access={large:!!prefs.large,motion:!!prefs.motion};}catch{}render(true);window.scrollTo(0,0);}};

